---@meta
-- Stormworks microcontroller Lua API definitions for lua-language-server.
-- Generated by `swlua init`; safe to edit or delete.

---Called every game tick (60 times per second).
function onTick() end

---Called every frame for each monitor connected to the script's video output.
function onDraw() end

---Called when a request made with async.httpGet completes.
---@param port integer
---@param request_body string the requested URL
---@param response_body string
function httpReply(port, request_body, response_body) end

---@class SWInput
input = {}
---Reads a number from the composite input (channels 1-32).
---@param index integer
---@return number
function input.getNumber(index) end
---Reads an on/off value from the composite input (channels 1-32).
---@param index integer
---@return boolean
function input.getBool(index) end

---@class SWOutput
output = {}
---Writes a number to the composite output (channels 1-32).
---@param index integer
---@param value number
function output.setNumber(index, value) end
---Writes an on/off value to the composite output (channels 1-32).
---@param index integer
---@param value boolean
function output.setBool(index, value) end

---@class SWProperty
property = {}
---Reads a number property of the microcontroller by its label.
---@param label string
---@return number
function property.getNumber(label) end
---Reads an on/off property of the microcontroller by its label.
---@param label string
---@return boolean
function property.getBool(label) end
---Reads a text property of the microcontroller by its label.
---@param label string
---@return string
function property.getText(label) end

---@class SWScreen
screen = {}
